import { Injectable, inject } from '@angular/core';
import { ActivatedRouteSnapshot, CanActivateFn, Router } from '@angular/router';

/**
 * The booking in progress (section 3.1). `seats` holds seat identifiers; a couch contributes
 * both of its identifiers.
 */
/** The values typed into the checkout form (section 7.1). */
export interface CheckoutValues {
  firstName: string;
  lastName: string;
  email: string;
  confirmEmail: string;
  phone: string;
  terms: boolean;
}

export interface Booking {
  screeningId: number;
  seats: string[];
  /** The checkout form values as last typed; absent until the form has been changed. */
  checkout?: CheckoutValues;
  /** Set once the booking is paid: the customer's email address (section 3.1). */
  paid?: { email: string };
}

/** One line of the summary: a single seat or a couch (section 6). */
export interface Ticket {
  /** Seat identifiers the ticket occupies: one for a seat, two for a couch. */
  ids: string[];
  row: number;
  /** The column number of a seat, or `Couch <a>-<b>`. */
  seat: string;
  /** Price in PLN. */
  price: number;
}

const STORAGE_KEY = 'cinescope.booking';
const COUCH_ROW = 15;
const COUCH_PRICE = 89;
const SEAT_ID_PATTERN = /^R(\d+)C(\d+)$/;

function seatId(row: number, column: number): string {
  return `R${row}C${column}`;
}

function parseSeatId(id: string): { row: number; column: number } | null {
  const match = SEAT_ID_PATTERN.exec(id);
  return match ? { row: Number(match[1]), column: Number(match[2]) } : null;
}

/** Price of one seat in the given row (section 5.4). */
function seatPrice(row: number): number {
  if (row <= 5) {
    return 25;
  }
  if (row <= 10) {
    return 32;
  }
  return 39;
}

/** Formats an amount as the price label, e.g. `25.00 PLN`. */
export function formatPrice(amount: number): string {
  return `${amount.toFixed(2)} PLN`;
}

/** The summary lines of a set of seat identifiers, ordered by row and then by column. */
export function ticketsFor(seatIds: readonly string[]): Ticket[] {
  const seats = seatIds
    .map(parseSeatId)
    .filter((seat): seat is { row: number; column: number } => seat !== null)
    .sort((a, b) => a.row - b.row || a.column - b.column);

  const tickets: Ticket[] = [];
  const couches = new Set<number>();
  for (const { row, column } of seats) {
    if (row === COUCH_ROW) {
      // Couches cover columns 1–2, 3–4, … 23–24, so a couch starts at an odd column.
      const start = column % 2 === 1 ? column : column - 1;
      if (couches.has(start)) {
        continue;
      }
      couches.add(start);
      tickets.push({
        ids: [seatId(row, start), seatId(row, start + 1)],
        row,
        seat: `Couch ${start}-${start + 1}`,
        price: COUCH_PRICE,
      });
    } else {
      tickets.push({
        ids: [seatId(row, column)],
        row,
        seat: String(column),
        price: seatPrice(row),
      });
    }
  }
  return tickets;
}

/** Keeps the booking in progress in `sessionStorage`, so it survives a reload. */
@Injectable({ providedIn: 'root' })
export class BookingService {
  /** The booking in progress, or null when there is none or it cannot be read. */
  load(): Booking | null {
    const raw = sessionStorage.getItem(STORAGE_KEY);
    if (raw === null) {
      return null;
    }
    try {
      return JSON.parse(raw) as Booking;
    } catch {
      return null;
    }
  }

  save(booking: Booking): void {
    sessionStorage.setItem(STORAGE_KEY, JSON.stringify(booking));
  }

  clear(): void {
    sessionStorage.removeItem(STORAGE_KEY);
  }

  /** The seats of the booking in progress when it belongs to the screening, otherwise none. */
  seatsFor(screeningId: string | undefined): string[] {
    const booking = this.load();
    return booking !== null && booking.screeningId === Number(screeningId) ? booking.seats : [];
  }

  /** Changes some fields of the booking in progress, keeping the others. Does nothing without one. */
  update(changes: Partial<Booking>): void {
    const booking = this.load();
    if (booking !== null) {
      this.save({ ...booking, ...changes });
    }
  }

  /**
   * Called once the seat map of a screening has loaded: keeps the booking when it belongs to
   * the screening, otherwise replaces it with an empty booking for the screening.
   */
  openFor(screeningId: number): void {
    if (this.load()?.screeningId !== screeningId) {
      this.save({ screeningId, seats: [] });
    }
  }
}

/**
 * Lets a route with a `:id` parameter be entered only with a booking in progress for that
 * screening that has at least one seat; otherwise redirects to `/` (section 3.1).
 */
export const bookingGuard: CanActivateFn = (route: ActivatedRouteSnapshot) => {
  const booking = inject(BookingService).load();
  const allowed =
    booking !== null &&
    booking.seats.length > 0 &&
    booking.screeningId === Number(route.paramMap.get('id'));
  return allowed || inject(Router).createUrlTree(['/']);
};
export interface Movie {
  id: number;
  title: string;
  genre: string;
  runtimeMinutes: number;
  format: 'PL dubbing' | 'PL subtitles';
}

export interface Screening {
  id: number;
  movieId: number;
  date: string;
  time: string;
  occupiedSeats: string[];
}

export interface Customer {
  firstName: string;
  lastName: string;
  email: string;
  /** Empty when not provided. */
  phone: string;
}

export interface Reservation {
  id: number;
  screeningId: number;
  /** Seat identifiers; a couch contributes both of its identifiers. */
  seats: string[];
  customer: Customer;
  /** Total in PLN. */
  totalPrice: number;
}

/** A reservation to be created: the backend assigns the `id`. */
export type NewReservation = Omit<Reservation, 'id'>;
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';
import { Movie, NewReservation, Reservation, Screening } from './models';

export const API_BASE_URL = 'http://localhost:3000';

@Injectable({ providedIn: 'root' })
export class ApiService {
  private readonly http = inject(HttpClient);

  getMovies(): Observable<Movie[]> {
    return this.http.get<Movie[]>(`${API_BASE_URL}/movies`);
  }

  getScreeningsByDate(date: string): Observable<Screening[]> {
    return this.http.get<Screening[]>(`${API_BASE_URL}/screenings`, { params: { date } });
  }

  getScreening(id: string): Observable<Screening> {
    return this.http.get<Screening>(`${API_BASE_URL}/screenings/${encodeURIComponent(id)}`);
  }

  getMovie(id: number): Observable<Movie> {
    return this.http.get<Movie>(`${API_BASE_URL}/movies/${id}`);
  }

  createReservation(reservation: NewReservation): Observable<Reservation> {
    return this.http.post<Reservation>(`${API_BASE_URL}/reservations`, reservation);
  }
}
const WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

/** Formats a date as an ISO date (YYYY-MM-DD) using the browser's local calendar. */
export function toIsoDate(date: Date): string {
  const year = String(date.getFullYear()).padStart(4, '0');
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

/** Parses a YYYY-MM-DD string into a local midnight Date; returns null for anything that is not a real calendar date. */
export function parseIsoDate(value: string | null | undefined): Date | null {
  if (!value || !/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    return null;
  }
  const [year, month, day] = value.split('-').map(Number);
  const date = new Date(year, month - 1, day);
  if (toIsoDate(date) !== value) {
    return null;
  }
  return date;
}

/** Local midnight of the given date. */
export function startOfDay(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate());
}

/** Returns the date `days` days after `date`. */
export function addDays(date: Date, days: number): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate() + days);
}

/** English full weekday name, e.g. "Tuesday". */
export function weekdayName(date: Date): string {
  return WEEKDAYS[date.getDay()];
}

/** Show date as `<Weekday> <D> <Mon> <HH:mm>`, e.g. "Tuesday 15 Sep 16:00". */
export function formatShowDate(date: Date, time: string): string {
  return `${weekdayName(date)} ${date.getDate()} ${MONTHS[date.getMonth()]} ${time}`;
}
