import { Component, Injectable, inject } from '@angular/core';
import { MAT_SNACK_BAR_DATA, MatSnackBar } from '@angular/material/snack-bar';

/** How long a toast stays visible, in milliseconds (section 3.2). */
const TOAST_DURATION_MS = 4000;

export interface ToastData {
  message: string;
}

/** The content of a toast; its host element carries the `toast` identifier (section 9.6). */
@Component({
  selector: 'app-toast',
  template: '{{ data.message }}',
  host: { 'data-testid': 'toast' },
})
export class ToastMessage {
  readonly data = inject<ToastData>(MAT_SNACK_BAR_DATA);
}

/** Shows short messages as toasts. Opening a toast replaces the one that is visible. */
@Injectable({ providedIn: 'root' })
export class ToastService {
  private readonly snackBar = inject(MatSnackBar);

  show(message: string): void {
    this.snackBar.openFromComponent(ToastMessage, {
      data: { message } satisfies ToastData,
      duration: TOAST_DURATION_MS,
    });
  }
}

import { Component, inject, signal } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import {
  AbstractControl,
  FormControl,
  FormGroup,
  ReactiveFormsModule,
  ValidationErrors,
  Validators,
} from '@angular/forms';
import { MatButtonModule } from '@angular/material/button';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { Router } from '@angular/router';
import { firstValueFrom } from 'rxjs';
import { ApiService } from '../api.service';
import { BookingService, CheckoutValues, formatPrice, ticketsFor } from '../booking';
import { ToastService } from '../toast/toast';

type FieldName = keyof CheckoutValues;

/** An email address: no spaces or `@` around one `@`, and a dot with characters on both sides in the domain. */
const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
/** Exactly nine digits (section 7). */
const PHONE_PATTERN = /^\d{9}$/;

const EMPTY_VALUES: CheckoutValues = {
  firstName: '',
  lastName: '',
  email: '',
  confirmEmail: '',
  phone: '',
  terms: false,
};

/** The message of each validation error of each field (section 7). */
const MESSAGES: Record<FieldName, Record<string, string>> = {
  firstName: {
    required: 'First name is required',
    minlength: 'First name must be at least 2 characters',
  },
  lastName: {
    required: 'Last name is required',
    minlength: 'Last name must be at least 2 characters',
  },
  email: {
    required: 'Email is required',
    pattern: 'Enter a valid email address',
  },
  confirmEmail: {
    required: 'Confirm email is required',
    mismatch: 'Email addresses do not match',
  },
  phone: {
    pattern: 'Phone number must be exactly 9 digits',
  },
  terms: {
    required: 'You must accept the terms and conditions',
  },
};

/** Confirm email must equal Email as typed. An empty value is left to the required check. */
function matchesEmail(control: AbstractControl): ValidationErrors | null {
  const email: unknown = control.parent?.get('email')?.value;
  return control.value === '' || control.value === email ? null : { mismatch: true };
}

/** The checkout: customer details and payment (section 7). */
@Component({
  selector: 'app-checkout',
  imports: [
    MatButtonModule,
    MatCheckboxModule,
    MatFormFieldModule,
    MatInputModule,
    ReactiveFormsModule,
  ],
  templateUrl: './checkout.html',
  styleUrl: './checkout.scss',
})
export class Checkout {
  private readonly api = inject(ApiService);
  private readonly bookings = inject(BookingService);
  private readonly router = inject(Router);
  private readonly toasts = inject(ToastService);

  /** The booking in progress; the route guard makes sure it exists. */
  private readonly booking = this.bookings.load();

  readonly tickets = ticketsFor(this.booking?.seats ?? []);
  readonly total = this.tickets.reduce((sum, ticket) => sum + ticket.price, 0);
  readonly totalLabel = formatPrice(this.total);

  /** True while the payment request is in flight. */
  readonly submitting = signal(false);

  /** The values typed before are restored, so the form survives going back and reloads (section 7.1). */
  readonly form = new FormGroup({
    firstName: new FormControl(this.booking?.checkout?.firstName ?? EMPTY_VALUES.firstName, {
      nonNullable: true,
      validators: [Validators.required, Validators.minLength(2)],
    }),
    lastName: new FormControl(this.booking?.checkout?.lastName ?? EMPTY_VALUES.lastName, {
      nonNullable: true,
      validators: [Validators.required, Validators.minLength(2)],
    }),
    email: new FormControl(this.booking?.checkout?.email ?? EMPTY_VALUES.email, {
      nonNullable: true,
      validators: [Validators.required, Validators.pattern(EMAIL_PATTERN)],
    }),
    confirmEmail: new FormControl(
      this.booking?.checkout?.confirmEmail ?? EMPTY_VALUES.confirmEmail,
      { nonNullable: true, validators: [Validators.required, matchesEmail] },
    ),
    phone: new FormControl(this.booking?.checkout?.phone ?? EMPTY_VALUES.phone, {
      nonNullable: true,
      validators: [Validators.pattern(PHONE_PATTERN)],
    }),
    terms: new FormControl(this.booking?.checkout?.terms ?? EMPTY_VALUES.terms, {
      nonNullable: true,
      validators: [Validators.requiredTrue],
    }),
  });

  constructor() {
    // The confirm-email check was made before the form existed, so it is run again now.
    this.form.controls.confirmEmail.updateValueAndValidity({ emitEvent: false });

    this.form.controls.email.valueChanges
      .pipe(takeUntilDestroyed())
      .subscribe(() => this.form.controls.confirmEmail.updateValueAndValidity());

    this.form.valueChanges
      .pipe(takeUntilDestroyed())
      .subscribe(() => this.bookings.update({ checkout: this.form.getRawValue() }));
  }

  /** The message to show under a field: only once it has been left, and only one. */
  errorOf(field: FieldName): string | null {
    const control = this.form.controls[field];
    if (!control.touched || !control.errors) {
      return null;
    }
    const messages = MESSAGES[field];
    const key = Object.keys(control.errors).find((name) => name in messages);
    return key === undefined ? null : messages[key];
  }

  /** Pays: sends the reservation if the form is valid, otherwise marks every field and stays. */
  async pay(): Promise<void> {
    if (this.submitting()) {
      return;
    }
    this.form.markAllAsTouched();
    if (this.form.invalid) {
      this.toasts.show('The form contains errors');
      return;
    }
    if (this.booking === null) {
      return;
    }

    const values = this.form.getRawValue();
    this.submitting.set(true);
    try {
      await firstValueFrom(
        this.api.createReservation({
          screeningId: this.booking.screeningId,
          seats: this.tickets.flatMap((ticket) => ticket.ids),
          customer: {
            firstName: values.firstName,
            lastName: values.lastName,
            email: values.email,
            phone: values.phone,
          },
          totalPrice: this.total,
        }),
      );
    } catch {
      this.submitting.set(false);
      this.toasts.show('Payment failed. Please try again.');
      return;
    }

    this.bookings.update({ paid: { email: values.email } });
    await this.router.navigate(['/confirmation']);
  }

  back(): void {
    if (this.booking !== null) {
      void this.router.navigate(['/screenings', this.booking.screeningId, 'summary']);
    }
  }
}
<h1 data-testid="checkout-title">Your details</h1>

<form class="details" [formGroup]="form">
  <mat-form-field subscriptSizing="dynamic">
    <mat-label data-testid="first-name-label">First name *</mat-label>
    <input matInput formControlName="firstName" data-testid="first-name-input" />
  </mat-form-field>
  @if (errorOf('firstName'); as message) {
  <p class="error" data-testid="first-name-error">{{ message }}</p>
  }

  <mat-form-field subscriptSizing="dynamic">
    <mat-label data-testid="last-name-label">Last name *</mat-label>
    <input matInput formControlName="lastName" data-testid="last-name-input" />
  </mat-form-field>
  @if (errorOf('lastName'); as message) {
  <p class="error" data-testid="last-name-error">{{ message }}</p>
  }

  <mat-form-field subscriptSizing="dynamic">
    <mat-label data-testid="email-label">Email *</mat-label>
    <input matInput formControlName="email" data-testid="email-input" />
  </mat-form-field>
  @if (errorOf('email'); as message) {
  <p class="error" data-testid="email-error">{{ message }}</p>
  }

  <mat-form-field subscriptSizing="dynamic">
    <mat-label data-testid="confirm-email-label">Confirm email *</mat-label>
    <input matInput formControlName="confirmEmail" data-testid="confirm-email-input" />
  </mat-form-field>
  @if (errorOf('confirmEmail'); as message) {
  <p class="error" data-testid="confirm-email-error">{{ message }}</p>
  }

  <mat-form-field subscriptSizing="dynamic">
    <mat-label data-testid="phone-label">Phone number</mat-label>
    <input matInput formControlName="phone" data-testid="phone-input" />
  </mat-form-field>
  @if (errorOf('phone'); as message) {
  <p class="error" data-testid="phone-error">{{ message }}</p>
  }

  <mat-checkbox
    class="terms"
    formControlName="terms"
    data-testid="terms-checkbox"
    (change)="form.controls.terms.markAsTouched()"
  >
    <span data-testid="terms-label">I accept the terms and conditions *</span>
  </mat-checkbox>
  @if (errorOf('terms'); as message) {
  <p class="error" data-testid="terms-error">{{ message }}</p>
  }
</form>

<div class="actions">
  <button mat-stroked-button type="button" data-testid="checkout-back-button" (click)="back()">
    Back
  </button>
  <button
    mat-flat-button
    type="button"
    data-testid="pay-button"
    [disabled]="submitting()"
    (click)="pay()"
  >
    {{ submitting() ? 'Processing…' : 'Pay ' + totalLabel }}
  </button>
</div>

import { Component, computed, effect, inject, linkedSignal, resource } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { MatButtonModule } from '@angular/material/button';
import { ActivatedRoute, Router } from '@angular/router';
import { firstValueFrom } from 'rxjs';
import { ApiService } from '../api.service';
import { BookingService } from '../booking';
import { formatShowDate, parseIsoDate } from '../dates';
import { Movie, Screening } from '../models';
import { ToastService } from '../toast/toast';

type SeatState = 'available' | 'selected' | 'unavailable' | 'accessible';

interface SeatView {
  column: number;
  /** Seat identifiers the seat occupies: one. */
  ids: string[];
  state: SeatState;
  gridColumn: string;
}

interface CouchView {
  start: number;
  end: number;
  /** Seat identifiers the couch occupies: two. */
  ids: string[];
  state: SeatState;
  gridColumn: string;
}

interface AisleView {
  gridColumn: string;
}

interface RowView {
  number: number;
  seats: SeatView[];
  couches: CouchView[];
  aisles: AisleView[];
}

interface SelectionLine {
  row: number;
  /** Seats of the row in column order, e.g. "11, 12" or "1-2". */
  seats: string;
}

interface LegendItem {
  state: SeatState;
  label: string;
}

const ROW_COUNT = 15;
const COLUMN_COUNT = 24;
const COUCH_ROW = 15;
/** Rows 1 to this number have no seats in columns 1–4 (the entrance). */
const ENTRANCE_LAST_ROW = 10;
/** Aisles sit after these columns; each is two grid tracks wide. */
const AISLE_AFTER_COLUMNS = [4, 20];
/** Grid tracks of the row labels; the seat columns occupy the tracks in between. */
const LEFT_LABEL_TRACK = 1;
const RIGHT_LABEL_TRACK = 30;
/** A booking holds at most this many seats; a couch counts as two. */
const MAX_SEATS = 10;

const LEGEND: LegendItem[] = [
  { state: 'available', label: 'Available' },
  { state: 'selected', label: 'Selected' },
  { state: 'unavailable', label: 'Unavailable' },
  { state: 'accessible', label: 'Accessible' },
];

/**
 * Grid track of a seat column. Track 1 is the left row label, tracks 2–29 hold the seat
 * columns with each aisle taking two tracks, track 30 is the right row label.
 */
function gridTrack(column: number): number {
  return 1 + column + (column > 4 ? 2 : 0) + (column > 20 ? 2 : 0);
}

function seatId(row: number, column: number): string {
  return `R${row}C${column}`;
}

function isAccessible(row: number, column: number): boolean {
  return row === 1 && column >= 10 && column <= 15;
}

/**
 * State of a seat or couch made of `ids`. Unavailable wins over selected; a couch is
 * selected only when both of its seats are, so it is never half-selected.
 */
function stateOf(
  ids: readonly string[],
  accessible: boolean,
  occupied: ReadonlySet<string>,
  selected: ReadonlySet<string>,
): SeatState {
  if (ids.some((id) => occupied.has(id))) {
    return 'unavailable';
  }
  if (ids.every((id) => selected.has(id))) {
    return 'selected';
  }
  return accessible ? 'accessible' : 'available';
}

function buildRows(occupied: ReadonlySet<string>, selected: ReadonlySet<string>): RowView[] {
  return Array.from({ length: ROW_COUNT }, (_, index) => {
    const number = index + 1;
    const seats: SeatView[] = [];
    const couches: CouchView[] = [];

    if (number === COUCH_ROW) {
      for (let start = 1; start < COLUMN_COUNT; start += 2) {
        const end = start + 1;
        const ids = [seatId(number, start), seatId(number, end)];
        couches.push({
          start,
          end,
          ids,
          state: stateOf(ids, false, occupied, selected),
          gridColumn: `${gridTrack(start)} / span 2`,
        });
      }
    } else {
      const firstColumn = number <= ENTRANCE_LAST_ROW ? 5 : 1;
      for (let column = firstColumn; column <= COLUMN_COUNT; column++) {
        const ids = [seatId(number, column)];
        seats.push({
          column,
          ids,
          state: stateOf(ids, isAccessible(number, column), occupied, selected),
          gridColumn: String(gridTrack(column)),
        });
      }
    }

    const aisles = AISLE_AFTER_COLUMNS.map((column) => ({
      gridColumn: `${gridTrack(column) + 1} / span 2`,
    }));

    return { number, seats, couches, aisles };
  });
}

@Component({
  selector: 'app-seat-selection',
  imports: [MatButtonModule],
  templateUrl: './seat-selection.html',
  styleUrl: './seat-selection.scss',
})
export class SeatSelection {
  private readonly api = inject(ApiService);
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);
  private readonly toasts = inject(ToastService);
  private readonly bookings = inject(BookingService);

  private readonly params = toSignal(this.route.paramMap, { requireSync: true });

  /** The screening id from the URL; undefined keeps the resource idle. */
  private readonly screeningId = computed(() => this.params().get('id') ?? undefined);

  readonly data = resource({
    params: () => this.screeningId(),
    loader: async ({ params: id }): Promise<{ screening: Screening; movie: Movie }> => {
      const screening = await firstValueFrom(this.api.getScreening(id));
      const movie = await firstValueFrom(this.api.getMovie(screening.movieId));
      this.bookings.openFor(screening.id);
      return { screening, movie };
    },
  });

  readonly screening = computed(() => (this.data.hasValue() ? this.data.value().screening : null));

  readonly showDate = computed(() => {
    const screening = this.screening();
    const date = screening ? parseIsoDate(screening.date) : null;
    return screening && date ? formatShowDate(date, screening.time) : '';
  });

  private readonly occupied = computed<ReadonlySet<string>>(
    () => new Set(this.screening()?.occupiedSeats ?? []),
  );

  /** Identifiers of the selected seats; a couch contributes both of its identifiers. Starts from the booking in progress. */
  readonly selectedIds = linkedSignal<string | undefined, ReadonlySet<string>>({
    source: this.screeningId,
    computation: (id) => new Set(this.bookings.seatsFor(id)),
  });

  readonly selectedCount = computed(() => this.selectedIds().size);

  readonly rows = computed<RowView[]>(() =>
    this.screening() ? buildRows(this.occupied(), this.selectedIds()) : [],
  );

  /** The selected-seats panel: one line per row with a selection, in row order. */
  readonly selectionLines = computed<SelectionLine[]>(() =>
    this.rows()
      .map((row) => {
        const picked = [
          ...row.seats
            .filter((seat) => seat.state === 'selected')
            .map((seat) => ({ column: seat.column, label: String(seat.column) })),
          ...row.couches
            .filter((couch) => couch.state === 'selected')
            .map((couch) => ({ column: couch.start, label: `${couch.start}-${couch.end}` })),
        ].sort((a, b) => a.column - b.column);
        return { row: row.number, seats: picked.map((item) => item.label).join(', ') };
      })
      .filter((line) => line.seats !== ''),
  );

  readonly legend = LEGEND;
  readonly leftLabelColumn = String(LEFT_LABEL_TRACK);
  readonly rightLabelColumn = String(RIGHT_LABEL_TRACK);

  constructor() {
    effect(() => {
      if (this.data.status() === 'error') {
        void this.router.navigate(['/']);
      }
    });
  }

  /**
   * Selects or deselects the seat or couch made of `ids`. Unavailable seats are ignored; a
   * selection that would exceed the cap is ignored and shows a toast. Deselecting is always allowed.
   */
  toggle(ids: readonly string[]): void {
    const screening = this.screening();
    const occupied = this.occupied();
    if (!screening || ids.some((id) => occupied.has(id))) {
      return;
    }

    const selected = new Set(this.selectedIds());
    if (ids.every((id) => selected.has(id))) {
      ids.forEach((id) => selected.delete(id));
    } else {
      const added = ids.filter((id) => !selected.has(id)).length;
      if (selected.size + added > MAX_SEATS) {
        this.toasts.show(`Maximum ${MAX_SEATS} seats per booking`);
        return;
      }
      ids.forEach((id) => selected.add(id));
    }
    this.selectedIds.set(selected);
    this.bookings.update({ seats: [...selected] });
  }

  cancel(): void {
    this.bookings.clear();
    void this.router.navigate(['/']);
  }

  continueToSummary(): void {
    const screening = this.screening();
    if (!screening || this.selectedCount() === 0) {
      return;
    }
    void this.router.navigate(['/screenings', screening.id, 'summary']);
  }
}
import { Component, computed, effect, inject, linkedSignal, resource } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { MatButtonModule } from '@angular/material/button';
import { ActivatedRoute, Router } from '@angular/router';
import { firstValueFrom } from 'rxjs';
import { ApiService } from '../api.service';
import { BookingService, formatPrice, ticketsFor } from '../booking';
import { Movie, Screening } from '../models';

/** A summary line with everything its template shows (section 6). */
interface SummaryItem {
  key: string;
  /** Seat identifiers of the line, used to remove it from the booking. */
  ids: string[];
  title: string;
  datetime: string;
  row: number;
  seat: string;
  price: number;
  priceLabel: string;
}

@Component({
  selector: 'app-summary',
  imports: [MatButtonModule],
  templateUrl: './summary.html',
  styleUrl: './summary.scss',
})
export class Summary {
  private readonly api = inject(ApiService);
  private readonly bookings = inject(BookingService);
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);

  private readonly params = toSignal(this.route.paramMap, { requireSync: true });

  /** The screening id from the URL; undefined keeps the resource idle. */
  private readonly screeningId = computed(() => this.params().get('id') ?? undefined);

  readonly data = resource({
    params: () => this.screeningId(),
    loader: async ({ params: id }): Promise<{ screening: Screening; movie: Movie }> => {
      const screening = await firstValueFrom(this.api.getScreening(id));
      const movie = await firstValueFrom(this.api.getMovie(screening.movieId));
      return { screening, movie };
    },
  });

  readonly screening = computed(() => (this.data.hasValue() ? this.data.value().screening : null));

  /** Seat identifiers of the booking in progress; a removed ticket is taken out of it. */
  private readonly seats = linkedSignal<string | undefined, string[]>({
    source: this.screeningId,
    computation: (id) => this.bookings.seatsFor(id),
  });

  readonly items = computed<SummaryItem[]>(() => {
    if (!this.data.hasValue()) {
      return [];
    }
    const { screening, movie } = this.data.value();
    const datetime = `${screening.date} ${screening.time}`;
    return ticketsFor(this.seats()).map((ticket) => ({
      key: ticket.ids.join(' '),
      ids: ticket.ids,
      title: movie.title,
      datetime,
      row: ticket.row,
      seat: ticket.seat,
      price: ticket.price,
      priceLabel: formatPrice(ticket.price),
    }));
  });

  readonly totalLabel = computed(() =>
    formatPrice(this.items().reduce((total, item) => total + item.price, 0)),
  );

  constructor() {
    effect(() => {
      if (this.data.status() === 'error') {
        void this.router.navigate(['/']);
      }
    });
  }

  /** Removes a ticket from the booking. Removing the last one opens the seat map. */
  remove(item: SummaryItem): void {
    const screening = this.screening();
    if (!screening) {
      return;
    }
    const seats = this.seats().filter((id) => !item.ids.includes(id));
    this.seats.set(seats);
    this.bookings.update({ seats });
    if (seats.length === 0) {
      this.openScreen('seats');
    }
  }

  back(): void {
    this.openScreen('seats');
  }

  confirm(): void {
    this.openScreen('checkout');
  }

  private openScreen(page: 'seats' | 'checkout'): void {
    const screening = this.screening();
    if (screening) {
      void this.router.navigate(['/screenings', screening.id, page]);
    }
  }
}
